    private static object Variant(Dictionary<string,object?> data){var result=new Dictionary<string,object?>(data);var options=new Dictionary<string,object?>();foreach(var key in new[]{"color","storage","ram","size","connectivity"}){if(data[key] is string text&&!string.IsNullOrWhiteSpace(text))options[key]=text;result.Remove(key);}result["options"]=options;return result;}
    private static object Settings(Dictionary<string,object?> data){var value=new Dictionary<string,object?>(data);value.Remove("reason");return new{key="commerce",value,reason=data["reason"]};}
    private static Dictionary<string,object?> SettingsContext(JsonElement row,string key)
    {
        var result=new Dictionary<string,object?>();if(row.ValueKind!=JsonValueKind.Object||!row.TryGetProperty("value",out var value))return result;if(key=="exchangeRateVnd"){result[key]=value.ToString();return result;}
        if(value.ValueKind==JsonValueKind.Object)foreach(var property in value.EnumerateObject())result[property.Name]=property.Value.ValueKind switch{JsonValueKind.True=>true,JsonValueKind.False=>false,JsonValueKind.Number=>property.Value.GetInt64(),JsonValueKind.String=>property.Value.GetString(),_=>property.Value.Clone()};return result;
    }
    private static object Promotion(Dictionary<string,object?> data)
    {
        var d=new Dictionary<string,object?>(data);var kind=d["targetKind"]?.ToString();d["allProducts"]=kind=="all";d["targets"]=kind=="product"?new[]{new Dictionary<string,object?>{{"productId",d["productId"]}}}:kind=="variant"?new[]{new Dictionary<string,object?>{{"variantId",d["variantId"]}}}:Array.Empty<Dictionary<string,object?>>();d.Remove("targetKind");d.Remove("productId");d.Remove("variantId");if(Convert.ToInt32(d["maxUses"])==0)d["maxUses"]=null;if(Convert.ToInt32(d["maxUsesPerCustomer"])==0)d["maxUsesPerCustomer"]=null;d["active"]=true;return d;
    }
